<script setup lang="ts">import { reactive,ref } from 'vue';import { ElMessage } from 'element-plus';import PageHeader from '@/components/PageHeader.vue';const dialog=ref(false);const form=reactive({name:'',phone:'',region:[],detail:'',default:false});const addresses=ref([{id:'1',name:'王先生',phone:'138****6618',address:'广东省广州市番禺区大学城教学路 18 号',default:true},{id:'2',name:'王同学',phone:'136****1052',address:'广东省韶关市浈江区大学路 288 号',default:false}]);function save(){dialog.value=false;ElMessage.success('地址已保存')};</script>
<template><PageHeader title="收货地址" description="地址会在下单时生成不可变快照，后续修改不影响历史订单。"><el-button type="primary" @click="dialog=true">新增地址</el-button></PageHeader><div class="address-grid"><article v-for="a in addresses" :key="a.id" class="paper-card"><header><b>{{a.name}}</b><span>{{a.phone}}</span><el-tag v-if="a.default" size="small">默认地址</el-tag></header><p>{{a.address}}</p><footer><el-button text>编辑</el-button><el-button text type="danger">删除</el-button><el-button v-if="!a.default" text>设为默认</el-button></footer></article></div><el-dialog v-model="dialog" title="新增收货地址" width="520"><el-form label-position="top"><div class="two"><el-form-item label="收货人"><el-input v-model="form.name"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone"/></el-form-item></div><el-form-item label="省 / 市 / 区"><el-cascader v-model="form.region" :options="[{value:'gd',label:'广东省',children:[{value:'gz',label:'广州市',children:[{value:'py',label:'番禺区'}]}]}]" style="width:100%"/></el-form-item><el-form-item label="详细地址"><el-input v-model="form.detail" type="textarea"/></el-form-item><el-checkbox v-model="form.default">设为默认地址</el-checkbox></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存地址</el-button></template></el-dialog></template>
<style scoped>.address-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.address-grid article{padding:22px}.address-grid header{display:flex;align-items:center;gap:12px}.address-grid header span{color:var(--muted)}.address-grid header .el-tag{margin-left:auto}.address-grid p{min-height:45px;color:#455752;line-height:1.7}.address-grid footer{padding-top:12px;border-top:1px solid var(--line)}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media(max-width:650px){.address-grid,.two{grid-template-columns:1fr}}</style>
